select 'Хитровка. Знак четырёх','Москва, начало XX века. Константин Станиславский и Владимир Гиляровский отправляются на Хитровку и оказываются участниками расследования загадочного убийства.',2023,129,(select "directorID" from public.directors where "fullName"='Карен Шахназаров' order by "directorID" limit 1),(select "genreID" from public.genres where "genreName"='Thriller' order by "genreID" limit 1),(select "actorID" from public.actors where "fullName"='Константин Крюков' order by "actorID" limit 1),0,'/assets/posters/khitrovka-znak-chetyryekh.jpg','https://www.mosfilm.ru/cinema/films/khitrovka-znak-chetyryekh/','https://rutube.ru/play/embed/e4815c220252ceac0ea9c0460b8cf5bc/','https://www.mosfilm.ru/cinema/films/khitrovka-znak-chetyryekh/','© Киноконцерн «Мосфильм». Официальный плеер правообладателя. Все права защищены.',true,array['thoughtful'],array['Полный фильм','Мосфильм','На русском'],3,true,'Русский'
where not exists(select 1 from public.movies where title='Хитровка. Знак четырёх' and "releaseYear"=2023);
select 'Решение о ликвидации','Оперативная группа получает задание найти и обезвредить опасного главаря боевиков. Военная драма о подготовке сложной спецоперации.',2018,96,(select "directorID" from public.directors where "fullName"='Александр Аравин' order by "directorID" limit 1),(select "genreID" from public.genres where "genreName"='War' order by "genreID" limit 1),(select "actorID" from public.actors where "fullName"='Дагун Омаев' order by "actorID" limit 1),0,'/assets/posters/reshenie-o-likvidatsii.jpg','https://www.mosfilm.ru/cinema/films/reshenie-o-likvidatsii/','https://www.youtube.com/embed/-dLBhMfVi3E','https://www.mosfilm.ru/cinema/films/reshenie-o-likvidatsii/','© Киноконцерн «Мосфильм». Официальный плеер правообладателя. Все права защищены.',true,array['adrenaline'],array['Полный фильм','Мосфильм','На русском'],5,true,'Русский'
where not exists(select 1 from public.movies where title='Решение о ликвидации' and "releaseYear"=2018);
select 'Анна Каренина. История Вронского','Спустя годы после гибели Анны Вронский встречает её взрослого сына. Воспоминания возвращают его к истории любви, изменившей несколько судеб.',2017,138,(select "directorID" from public.directors where "fullName"='Карен Шахназаров' order by "directorID" limit 1),(select "genreID" from public.genres where "genreName"='Romance' order by "genreID" limit 1),(select "actorID" from public.actors where "fullName"='Елизавета Боярская' order by "actorID" limit 1),0,'/assets/posters/anna-karenina-istoriya-vronskogo.jpg','https://www.mosfilm.ru/cinema/films/anna-karenina-istoriya-vronskogo/','https://www.youtube.com/embed/ijqwV4wje_E','https://www.mosfilm.ru/cinema/films/anna-karenina-istoriya-vronskogo/','© Киноконцерн «Мосфильм». Официальный плеер правообладателя. Все права защищены.',true,array['romantic','emotional'],array['Полный фильм','Мосфильм','На русском'],4,true,'Русский'
where not exists(select 1 from public.movies where title='Анна Каренина. История Вронского' and "releaseYear"=2017);
select 'Сдается дом со всеми неудобствами','Несколько семей приезжают на отдых и обнаруживают, что им сдали один и тот же дом. Незнакомым людям приходится договариваться и жить вместе.',2016,91,(select "directorID" from public.directors where "fullName"='Вера Сторожева' order by "directorID" limit 1),(select "genreID" from public.genres where "genreName"='Comedy' order by "genreID" limit 1),(select "actorID" from public.actors where "fullName"='Светлана Ходченкова' order by "actorID" limit 1),0,'/assets/posters/sdaetsya-dom-so-vsemi-neudobstvami.jpg','https://www.mosfilm.ru/cinema/films/sdaetsya-dom-so-vsemi-neudobstvami/','https://www.youtube.com/embed/uy2E5CRXlnA','https://www.mosfilm.ru/cinema/films/sdaetsya-dom-so-vsemi-neudobstvami/','© Киноконцерн «Мосфильм». Официальный плеер правообладателя. Все права защищены.',true,array['happy','cozy'],array['Полный фильм','Мосфильм','На русском'],1,true,'Русский'
where not exists(select 1 from public.movies where title='Сдается дом со всеми неудобствами' and "releaseYear"=2016);
select 'Дорога на Берлин','Молодой офицер и сопровождающий его солдат оказываются за линией фронта. Совместный путь становится испытанием доверия и человечности.',2015,83,(select "directorID" from public.directors where "fullName"='Сергей Попов' order by "directorID" limit 1),(select "genreID" from public.genres where "genreName"='War' order by "genreID" limit 1),(select "actorID" from public.actors where "fullName"='Валерий Ненашев' order by "actorID" limit 1),0,'/assets/posters/doroga-na-berlin.jpg','https://www.mosfilm.ru/cinema/films/doroga-na-berlin/','https://www.youtube.com/embed/DjHTWMP_T1U','https://www.mosfilm.ru/cinema/films/doroga-na-berlin/','© Киноконцерн «Мосфильм». Официальный плеер правообладателя. Все права защищены.',true,array['emotional','thoughtful'],array['Полный фильм','Мосфильм','На русском'],4,true,'Русский'
