select 'Владивосток','Молодой военнослужащий бежит во Владивосток и знакомится с девушкой, которая обещает помочь ему выбраться из страны. Романтическое знакомство оборачивается опасной историей.',2021,97,(select "directorID" from public.directors where "fullName"='Антон Борматов' order by "directorID" limit 1),(select "genreID" from public.genres where "genreName"='Drama' order by "genreID" limit 1),(select "actorID" from public.actors where "fullName"='Андрей Грызлов' order by "actorID" limit 1),0,'/assets/posters/vladivostok.jpg','https://www.mosfilm.ru/cinema/films/vladivostok/','https://rutube.ru/play/embed/6dd052a50f9a9d219092ef75f05f6607/','https://www.mosfilm.ru/cinema/films/vladivostok/','© Киноконцерн «Мосфильм». Официальный плеер правообладателя. Все права защищены.',true,array['romantic','adrenaline'],array['Полный фильм','Мосфильм','На русском'],4,true,'Русский'
where not exists(select 1 from public.movies where title='Владивосток' and "releaseYear"=2021);
